    mask = cinema['id'].mod(2).eq(1) & cinema['description'].notna() & cinema['description'].ne('boring')
    return cinema.loc[mask].sort_values('rating', ascending=False)

def not_boring_movies(cinema: pd.DataFrame) -> pd.DataFrame:
    df =   cinema[(cinema.id % 2 == 1) & (cinema.description.notna()) & (cinema.description != 'boring')]
    return   df.sort_values('rating', ascending=False)

def find_employees(employees: pd.DataFrame) -> pd.DataFrame:
    mask = employees['salary'].lt(30000) & employees['manager_id'].notna() & ~employees['manager_id'].isin(employees['employee_id'])
    return employees.loc[mask, ['employee_id']].sort_values('employee_id')
